import type { Metadata } from "next";
import { LegalDraft, type DraftSection } from "@/components/LegalDraft";

export const metadata: Metadata = { title: "Privacy Policy — Draft", robots: { index: false, follow: false } };

const sections: DraftSection[] = [
  { id: "scope", title: "About this draft", body: <><p>Cubyfit is a fitness, nutrition, habit-tracking and personal-growth application developed and operated by Mohamed Radouan, Marouan Younsi and Mouad Mezian in Casablanca, Morocco (“Cubyfit,” “we,” or “us”). This draft explains what information we process, why we use it, who provides supporting services, and how users can manage or request deletion of their information.</p><p>Privacy contact: <strong>[VERIFIED PRIVACY EMAIL PENDING]</strong>. A postal contact address and the final legal controller description must be confirmed before publication.</p></> },
  { id: "information", title: "1. Information We Process", body: <><p><strong>Account:</strong> Name, email, account identifier, sign-in method, verification and recovery information, and information from Google or Apple if you choose social sign-in. Clerk provides authentication; Cubyfit does not maintain a separate password database.</p><p><strong>Fitness and growth:</strong> Information you enter or generate through the features you use, including date of birth, height, weight, target weight, fitness goals, activity and experience, workouts, routines, measurements, habits, schedules, completions, streaks, nutrition targets, meals, saved foods, preferences, reminders and favorites. Some of this may be sensitive under applicable law.</p><p><strong>Purchases:</strong> Account and product identifiers, entitlement and subscription status through RevenueCat and the applicable store. Payments are handled by Google Play or Apple&apos;s App Store, not by direct entry of payment-card details in Cubyfit.</p><p><strong>Technical data:</strong> Depending on platform and settings, service providers may process device and operating-system details, app version, diagnostics, performance, IP address, service identifiers, advertising identifiers and ad events. Website hosting and support requests may involve ordinary request information and information you send us.</p></> },
  { id: "local", title: "2. Local Storage and Optional Cloud Backup", body: <><p>Supported fitness, nutrition, habit and progress records are saved first in an account-specific SQLite database on your device. Guest records are separate. A downloaded food catalog and some shared settings are outside that account database.</p><p>Choosing <strong>Back up my data</strong> synchronizes supported records to Convex under your authenticated identity. Choosing <strong>Keep it on this device</strong> pauses fitness-data synchronization; it does not delete an existing cloud copy. Pending changes and unresolved conflicts may remain locally. The backup setting does not turn off authentication, subscription checks, diagnostics, advertising processing or security operations.</p><p>Device transfers and operating-system backups may copy local files separately. Cubyfit does not add application-level SQLCipher encryption to the SQLite database.</p></> },
  { id: "purposes", title: "3. How We Use Information", body: <><p>We use information to manage accounts; provide fitness, nutrition, workout, habit and progress features; save settings and optional cloud backups; calculate requested estimates; manage entitlements; deliver reminders; maintain service reliability and security; show ads to eligible free users subject to applicable choices; respond to support and deletion requests; and meet applicable legal obligations.</p><p>We do not intend to retain identifiable fitness statistics solely for our own business analytics after account deletion. We do not sell personal fitness records as a customer-data product. <strong>Before publication:</strong> Map actual internal analytics, processing purposes and legal bases for each relevant jurisdiction.</p></> },
  { id: "advertising", title: "4. Advertising and Privacy Choices", body: <><p>The Android app may show Google AdMob ads to eligible free users. Ad providers may process device and advertising identifiers, IP address, ad interactions and related technical information. Google UMP presents advertising privacy choices where configured and required. The applicable choices vary by region and provider.</p><p>The app checks UMP permission before loading an interstitial. Declining optional advertising consent does not disable core tracking features or unrelated services. We do not intentionally send individual nutrition logs, measurements or habit records to ad providers for targeting. Cubyfit Pro is intended to be ad-free while eligible entitlement is active.</p><p><strong>Before publication:</strong> Add and verify an ordinary in-app privacy-options entry point and regional messages. The current privacy-options form is reachable only through an internal testing screen.</p></> },
  { id: "providers", title: "5. Service Providers", body: <><ul><li><strong>Clerk:</strong> Authentication, identity and sessions.</li><li><strong>Convex:</strong> Authenticated operations and optional cloud backup.</li><li><strong>RevenueCat and Google Play or Apple:</strong> Entitlements, purchases and billing.</li><li><strong>Google AdMob and UMP:</strong> Advertising and advertising choices.</li><li><strong>Sentry:</strong> Error reports and reliability diagnostics.</li><li><strong>Cloudflare:</strong> Protected food-catalog delivery and access controls.</li><li><strong>Vercel:</strong> Website hosting.</li></ul><p>Providers may process information under their own policies and retention rules. The protected food-catalog gateway receives authenticated account information and source IP for access controls; its downloaded catalog is separate from your personal diary.</p></> },
  { id: "transfers", title: "6. International Processing", body: <p>Service providers may process information outside your country. Locations and safeguards depend on their configurations and the laws applicable to users. <strong>Before publication:</strong> Complete a professional review of Moroccan Law 09-08, CNDP obligations, relevant international transfers, GDPR and any other launch-market requirements. Specify the applicable mechanisms and controller details.</p> },
  { id: "retention", title: "7. Data Retention", body: <><p>Account and app records are kept while needed to provide the service, until deletion or an applicable retention obligation. Local records stay on a device until removed through app or device operations; pausing cloud backup does not erase existing Convex records.</p><p>After a verified account-deletion request, the backend blocks private cloud operations and deletes supported account-owned Convex records, then requests deletion of the matching RevenueCat customer and Clerk identity. Failures may cause retries and delay completion. A limited deletion-status job containing account identifiers, receipt, stage and timestamps remains about 30 days <strong>after completion</strong>; incomplete jobs remain until resolved.</p><p>The device observing completion removes its matching account SQLite database. Offline devices cannot be erased remotely. If a device reconnects after the status record expires, automatic cleanup may no longer occur; its app data may require manual clearing. Guest data, shared catalog files, operating-system backups, store transactions and provider records are outside this cleanup. Sentry, advertising, Cloudflare and provider backups may have separate retention periods that must be verified before publication.</p></> },
  { id: "deletion", title: "8. Account Deletion", body: <><p>In the signed-in app, go to <strong>Account → Data &amp; Privacy → Delete Account</strong>. Enter <code>DELETE-ACCOUNT</code>, complete Clerk email-code reverification and submit. The app shows available progress while the backend processes deletion. On completion it removes supported account-owned active cloud records and requests deletion of the corresponding Clerk and RevenueCat customer records, subject to the limits above.</p><p>Deleting your Cubyfit account does not cancel an active Google Play or App Store subscription. See the <a href="/delete-account">deletion page</a>. Its outside-app request channel must be established before these pages are published.</p></> },
  { id: "rights", title: "9. Your Privacy Rights", body: <p>Depending on applicable law, you may request access, correction or deletion; object to or restrict processing; withdraw consent where applicable; ask about transfers; or exercise other applicable rights. Contact <strong>[VERIFIED PRIVACY EMAIL PENDING]</strong>. We may verify your identity before handling account-related requests. You may also contact a relevant data-protection authority.</p> },
  { id: "security", title: "10. Security", body: <p>Cubyfit uses authenticated backend access, account-specific storage, cloud access controls and encrypted service connections where applicable. Supported secure storage holds authentication tokens and deletion receipts. Its fitness SQLite file is not separately encrypted at the application level. No electronic service can be guaranteed completely secure. Report suspected unauthorized access through the verified privacy contact once established.</p> },
  { id: "children", title: "11. Children and Age Eligibility", body: <p><strong>Before publication:</strong> Finalize the minimum age, age screening, applicable parental consent and minor-specific SDK and advertising treatment. The founders&apos; proposed 13+ worldwide audience is not yet an implemented eligibility rule.</p> },
  { id: "changes", title: "12. Changes", body: <p>We may update this policy when the service or legal requirements change. The published version will show its effective date; where required, we will provide additional notice or request consent.</p> },
  { id: "contact", title: "13. Contact", body: <p><strong>Cubyfit</strong><br />Mohamed Radouan, Marouan Younsi and Mouad Mezian<br />Casablanca, Morocco<br />Postal address: <strong>[BUSINESS POSTAL ADDRESS PENDING]</strong><br />Email: <strong>[VERIFIED PRIVACY EMAIL PENDING]</strong><br />Website: <a href="https://cubyfit.app">cubyfit.app</a></p> },
];

