  return <LegalDraft title="Privacy Policy" description="A technical drafting version covering Cubyfit's local records, optional backup and supporting providers." sections={sections} note="This policy is not finalized. Contact, legal bases, age treatment, international transfers and provider retention remain under review. Do not publish it as the operative Privacy Policy." />;
